def compute(vars):
    start_value = vars["v1"]
    end_value = vars["v2"]
    change = end_value - start_value
    return {
        "value": change,
        "trace": {
            "start_value": start_value,
            "end_value": end_value,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": None
            }
        }
    }
